def clamp(x, lo, hi):
    return max(lo, min(hi, x))


def format_bytes(n):
    units = ['B', 'KB', 'MB', 'GB', 'TB']
    size = float(n)
    unit_index = 0
    while size >= 1024 and unit_index < len(units) - 1:
        size /= 1024
        unit_index += 1
    return f"{size:.1f} {units[unit_index]}"
